133	            Map<String, Object> map = new LinkedHashMap<>();
134	            map.put("id", m.getId());
135	            map.put("workspaceId", m.getWorkspaceId());
136	            map.put("userId", m.getUserId());
137	
138	            User user = userMapper.findById(m.getUserId());
139	            map.put("username", user != null ? user.getUsername() : null);
140	            map.put("memberRole", m.getMemberRole());
141	            map.put("createdAt", m.getCreatedAt());
142	            result.add(map);
143	        }
144	
145	        return ApiResponse.success(result);
146	    }
