148	    @DeleteMapping("/members/{id}")
149	    public ApiResponse<Object> removeMember(@PathVariable Long id) {
150	        WorkspaceMember member = memberService.getMemberById(id);
151	        if (member == null) {
152	            return ApiResponse.error(404, "成员记录不存在");
153	        }
154	        memberService.removeMember(id);
155	        return ApiResponse.success("移除成功", null);
156	    }
